import { execFileSync } from 'node:child_process';
import { resolve } from 'node:path';
import { encode as rawEncode, rfc8949EncodeOptions } from 'cborg';
import { decodeRestricted, encodeCanonical, V2CborError } from '../../../src/v2/cbor.js';
import { assetId, merkleRoot, nullifier, outputId, policyDigest, v2Hash } from '../../../src/v2/identifiers.js';

const root = process.env.SOPHIADOS_DIR ?? resolve(process.cwd(), '../sophiados');
const commit = 'eae340b8351699b74fe2c1a5cf8c65896e598474';
const show = (path: string) => execFileSync('git', ['-C', root, 'show', `${commit}:${path}`]).toString();
const known = JSON.parse(show('contracts/conformance/fixtures/scarcity-v2/scarcity-core-known-answers.json'));
const positive = JSON.parse(show('contracts/conformance/fixtures/scarcity-v2/positive.json'));
const transition = positive.cases.find((item: any) => item.id === 'core-transition-known-answer');
const hex = (value: string) => { if (!/^[0-9a-f]+$/.test(value) || value.length % 2 !== 0) throw new V2CborError('decode-limit'); return Uint8Array.from(Buffer.from(value, 'hex')); };
const text = (value: Uint8Array) => Buffer.from(value).toString('hex');
const policy = hex(known.canonical.policy);
if (known.canonical.policy.length % 2 !== 0 || text(encodeCanonical(decodeRestricted(policy))) !== known.canonical.policy) throw new Error('SophiaDOS policy canonical bytes failed');
if (text(policyDigest(decodeRestricted(policy))) !== known.digests.policy) throw new Error('SophiaDOS policy digest failed');
const asset = decodeRestricted(hex(known.canonical.asset));
if (text(encodeCanonical(asset)) !== known.canonical.asset || text(assetId(asset)) !== known.digests.asset_id) throw new Error('SophiaDOS asset identity failed');
const domain = hex('3333333333333333333333333333333333333333333333333333333333333333');
const source = { transaction_id: new Uint8Array(32).fill(0x12), output_index: 0, output_commitment: new Uint8Array(32).fill(0x13) };
const inputOutputId = outputId(source.transaction_id, source.output_index, source.output_commitment);
const inputNullifier = nullifier(domain, inputOutputId);
if (!transition) throw new Error('SophiaDOS transition input missing');
if (text(inputOutputId) !== transition.input.inputs[0].output_id) throw new Error('input output identity failed');
const outputs = [7, 3, 1].map((amount, index) => { const recipient_key = new Uint8Array(32).fill([0x88, 0xaa, 0xcc][index]); const provenance = { kind: 'transition' }; const output_commitment = v2Hash('output-commitment', encodeCanonical({ asset_id: hex(known.digests.asset_id), amount, recipient_key, spend_domain: domain, provenance })); return { asset_id: hex(known.digests.asset_id), amount, recipient_key, spend_domain: domain, provenance, output_commitment }; });
const transaction = { spend_domain: domain, inputs: [{ output_id: inputOutputId, nullifier: inputNullifier, owner_key_id: new Uint8Array(32).fill(0x66) }], outputs };
const transactionId = v2Hash('transaction', encodeCanonical(transaction));
if (text(transactionId) !== known.digests.transaction_id) throw new Error('SophiaDOS transaction identity failed');
const ids = outputs.map((output, index) => outputId(transactionId, index, output.output_commitment));
ids.forEach((id: Uint8Array, index: number) => { if (text(nullifier(domain, id)) !== known.outputs[index].nullifier) throw new Error(`nullifier ${index} failed`); });
ids.forEach((id, index) => { if (text(id) !== known.outputs[index].output_id) throw new Error(`output identity ${index} failed`); });
if (text(merkleRoot([])) !== known.merkle['0'] || text(merkleRoot(ids.slice(0, 1))) !== known.merkle['1'] || text(merkleRoot(ids)) !== known.merkle['3']) throw new Error('Merkle known answers failed');
const negatives: Record<string, string> = { ...known.canonical_negative_values, trailing_bytes: `${known.canonical.policy}00`, depth_limit: `${'81'.repeat(33)}01`, array_limit: `990101${'80'.repeat(257)}`, map_limit: Buffer.from(rawEncode(new Map(Array.from({ length: 257 }, (_, i) => [`k${i}`, 0])), rfc8949EncodeOptions)).toString('hex'), text_limit: `791001${'61'.repeat(4097)}`, byte_limit: `5a00010001${'00'.repeat(65537)}`, message_limit: `5a00100001${'00'.repeat(1048577)}` };
for (const [name, expectedCategory] of Object.entries(known.canonical_negative)) { const value = negatives[name]; if (!value) throw new Error(`missing negative input: ${name}`); try { decodeRestricted(hex(value)); throw new Error(`negative accepted: ${name}`); } catch (error) { if (error instanceof V2CborError && error.category !== expectedCategory) throw new Error(`negative category mismatch: ${name}`); else if (!(error instanceof V2CborError)) throw error; } }
const expectEncode = (value: unknown, category: string) => { try { encodeCanonical(value); throw new Error('encode accepted'); } catch (error) { if (!(error instanceof V2CborError) || error.category !== category) throw error; } };
expectEncode(1.5, 'decode-limit'); expectEncode(Number.NaN, 'decode-limit'); expectEncode(Number.POSITIVE_INFINITY, 'decode-limit'); expectEncode(undefined, 'decode-limit'); expectEncode([undefined], 'decode-limit'); const sparse: unknown[] = []; sparse.length = 1; expectEncode(sparse, 'decode-limit'); expectEncode(Symbol('forbidden'), 'decode-limit'); expectEncode(() => 1, 'decode-limit'); expectEncode(new Date(0), 'decode-limit'); expectEncode(new Map([[1, 0]]), 'schema'); expectEncode([...[Array(257).keys()]], 'decode-limit'); expectEncode(new Uint8Array(65537), 'decode-limit'); expectEncode('x'.repeat(4097), 'decode-limit'); expectEncode(Array.from({ length: 17 }, () => new Uint8Array(65536)), 'decode-limit'); const deep: any[] = []; let cursor: any = deep; for (let i = 0; i < 33; i++) { cursor.push([]); cursor = cursor[0]; } expectEncode(deep, 'decode-limit');
console.log('V2 native identifier/CBOR vectors: passed');
